# Generates static pages from one shared layout so header/footer/sidebars stay identical.
# Each LAYOUT maps to a Django base template (see README).
LOGO='<svg viewBox="0 0 40 40" aria-hidden="true"><circle cx="20" cy="20" r="20" fill="#1e4d3b"/><path d="M12 28c0-9 6-15 17-15 0 10-6 16-15 16m0 0c2-5 5-9 10-12" fill="none" stroke="#f2a93b" stroke-width="2.5" stroke-linecap="round"/></svg>'
CDN_CSS='<link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><link href="https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@0,500;0,600;1,400&family=Hanken+Grotesk:wght@400;500;600;700&display=swap" rel="stylesheet">'
def css(r): return CDN_CSS+''.join(f'<link rel="stylesheet" href="{r}assets/css/{n}.css">' for n in ['style','marketplace','dashboard','responsive'])
def js(r,extra): return '<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>'+''.join(f'<script src="{r}assets/js/{n}.js"></script>' for n in ['data','main']+extra)
CONFIRM='<div class="modal fade" id="confirmModal" tabindex="-1" aria-labelledby="cmT" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h2 class="modal-title h5" id="cmT">Please confirm</h2><button class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"></div><div class="modal-footer"><button class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button class="btn btn-danger" data-ok>Confirm</button></div></div></div></div>'
import json
CATS=[('vintage-electronics','tv','Vintage Electronics'),('antiques','clock-history','Antiques'),('handicrafts','palette','Handicrafts'),('brass-copper','lamp','Brass & Copper'),('furniture','house-heart','Wooden Furniture'),('textiles','bag','Handloom'),('home-decor','image','Home Decor'),('collectibles','camera','Collectibles')]
