import os
def w(path,txt):
    os.makedirs(os.path.dirname(path) or '.',exist_ok=True); open(path,'w').write(txt)
for f,(t,b,e) in P.items(): w(f,pub('',t,b,e))
for f,(t,b,e) in S.items(): w('seller/'+f,dash('seller','../',t,b,e))
for f,(t,b,e) in A.items(): w('platform-admin/'+f,dash('platform-admin','../',t,b,e))
print(len(P)+len(S)+len(A),'pages')
